// Calculate 7 days ago for filtering
const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

return [{
  json: {
    seven_days_ago: sevenDaysAgo.toISOString(),
    today: now.toISOString(),
    week_start: sevenDaysAgo.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
    week_end: now.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
  }
}];

const items = $input.all();

if (items.length === 0) {
  return [{
    json: {
      has_data: false,
      log_text: 'No calls were logged this week.',
      total_calls: 0,
      week_start: $('Calculate Date Range').first().json.week_start,
      week_end: $('Calculate Date Range').first().json.week_end
    }
  }];
}

// Build a text representation of all log entries
const logLines = items.map((item, i) => {
  const d = item.json;
  return `${i + 1}. [${d.Timestamp || 'N/A'}] Caller: ${d['Caller Name'] || 'Unknown'} (${d['Caller Phone'] || 'N/A'}) | Duration: ${d['Duration (s)'] || 0}s | Summary: ${d.Summary || 'N/A'} | Actions: ${d['Actions Taken'] || 'none'}`;
});

// Compute basic stats
const totalCalls = items.length;
const totalDuration = items.reduce((sum, item) => sum + (parseInt(item.json['Duration (s)']) || 0), 0);
const avgDuration = Math.round(totalDuration / totalCalls);
const rsvpCount = items.filter(item => (item.json['Actions Taken'] || '').includes('rsvp_guest')).length;
const escalationCount = items.filter(item => (item.json['Actions Taken'] || '').includes('escalate')).length;

return [{
  json: {
    has_data: true,
    log_text: logLines.join('\n'),
    total_calls: totalCalls,
    total_duration_seconds: totalDuration,
    avg_duration_seconds: avgDuration,
    rsvp_count: rsvpCount,
    escalation_count: escalationCount,
    week_start: $('Calculate Date Range').first().json.week_start,
    week_end: $('Calculate Date Range').first().json.week_end
  }
}];

