const response = $input.first().json;
const stats = $('Aggregate Log Entries').first().json;

let summary = 'No summary available.';
if (response.content && Array.isArray(response.content)) {
  summary = response.content
    .filter(block => block.type === 'text')
    .map(block => block.text)
    .join('\n');
} else if (typeof response.content === 'string') {
  summary = response.content;
}

const emailBody = `<html><body style="font-family: Arial, sans-serif; color: #333;">
<h2 style="color: #2c5282;">Weekly Auto-Agent Summary</h2>
<p style="color: #718096;">Report period: ${stats.week_start} &ndash; ${stats.week_end}</p>
<hr style="border: 1px solid #e2e8f0;">

<h3>Quick Stats</h3>
<table style="border-collapse: collapse; width: 100%; max-width: 400px;">
  <tr><td style="padding: 6px 12px; border: 1px solid #e2e8f0;"><strong>Total Calls</strong></td><td style="padding: 6px 12px; border: 1px solid #e2e8f0;">${stats.total_calls}</td></tr>
  <tr><td style="padding: 6px 12px; border: 1px solid #e2e8f0;"><strong>RSVPs Made</strong></td><td style="padding: 6px 12px; border: 1px solid #e2e8f0;">${stats.rsvp_count}</td></tr>
  <tr><td style="padding: 6px 12px; border: 1px solid #e2e8f0;"><strong>Escalations</strong></td><td style="padding: 6px 12px; border: 1px solid #e2e8f0;">${stats.escalation_count}</td></tr>
  <tr><td style="padding: 6px 12px; border: 1px solid #e2e8f0;"><strong>Avg Call Duration</strong></td><td style="padding: 6px 12px; border: 1px solid #e2e8f0;">${stats.avg_duration_seconds}s</td></tr>
</table>

<h3>AI Summary</h3>
<div style="background: #f7fafc; padding: 16px; border-radius: 8px; border-left: 4px solid #2c5282;">
${summary.replace(/\n/g, '<br>')}
</div>

<hr style="border: 1px solid #e2e8f0; margin-top: 24px;">
<p style="font-size: 12px; color: #a0aec0;">This report was automatically generated by ClubDesk Auto-Agent. Do not reply to this email.</p>
</body></html>`;

return [{
  json: {
    email_body: emailBody,
    subject: `[ClubDesk] Auto-Agent Weekly Summary (${stats.week_start} - ${stats.week_end})`,
    week_start: stats.week_start,
    week_end: stats.week_end
  }
}];
